export function Approval({
  itemTitle = "{{itemTitle}}",
  requester = "{{requester}}",
  approver = "{{approver}}",
  decision = "{{decision}}",
  accent = "{{accent}}",
}) {
  const icons = {
    pending: { svg: "<svg viewBox=\"0 0 16 16\" width=\"16\" height=\"16\" fill=\"none\" aria-hidden=\"true\"><circle cx=\"8\" cy=\"8\" r=\"6.25\" stroke=\"currentColor\" stroke-width=\"1.5\"/><path d=\"M8 4.5V8l2.5 1.5\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>", color: accent },
    approved: { svg: "<svg viewBox=\"0 0 16 16\" width=\"16\" height=\"16\" fill=\"none\" aria-hidden=\"true\"><path d=\"M3 8.5l3 3 7-7\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>", color: "#2f8a52" },
    rejected: { svg: "<svg viewBox=\"0 0 16 16\" width=\"16\" height=\"16\" fill=\"none\" aria-hidden=\"true\"><path d=\"M4 4l8 8M12 4l-8 8\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg>", color: "#b23b3b" },
  };
  const active = icons[decision] ?? icons.pending;
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", maxWidth: 340, padding: 20, background: "#FAF7F2",
      color: "#241430", border: "1.5px solid #24143020", borderRadius: 14, borderLeft: `4px solid ${accent}` }}>
      <p style={{ margin: "0 0 4px", fontSize: 12, color: "#24143099", textTransform: "uppercase", letterSpacing: ".04em" }}>Requested by {requester}</p>
      <h3 style={{ margin: "0 0 12px", fontSize: 17, fontWeight: 600 }}>{itemTitle}</h3>
      <div style={{ display: "inline-flex", alignItems: "center", gap: 6, padding: "4px 10px 4px 8px", borderRadius: 999, background: "#24143010", marginBottom: 10 }}>
        <span style={{ color: active.color, display: "inline-flex" }} dangerouslySetInnerHTML={{ __html: active.svg }} />
        <span style={{ fontWeight: 600, fontSize: 13, textTransform: "capitalize" }}>{decision}</span>
      </div>
      <p style={{ margin: 0, fontSize: 14 }}>Awaiting approval from <strong>{approver}</strong></p>
    </div>
  );
}
